package com.example.billing.persistence;
import com.example.billing.domain.*; import java.time.*; import java.util.*; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.stereotype.Repository;
public final class Repositories { private Repositories(){} @Repository public interface CustomerRepository extends JpaRepository<Customer,UUID>{boolean existsByEmail(String email);List<Customer> findAllByOrderByCreatedAtAsc();} @Repository public interface ProductRepository extends JpaRepository<Product,UUID>{List<Product> findAllByOrderByNameAscIdAsc();} @Repository public interface PricePlanRepository extends JpaRepository<PricePlan,UUID>{Optional<PricePlan> findByIdAndActiveTrue(UUID id);List<PricePlan> findAllByOrderByProductIdAscBillingTypeAscIdAsc();} @Repository public interface SubscriptionRepository extends JpaRepository<Subscription,UUID>{List<Subscription> findByCustomerIdOrderByStartDateAscIdAsc(UUID id);} @Repository public interface InvoiceRepository extends JpaRepository<Invoice,UUID>{Optional<Invoice> findBySubscriptionIdAndBillingPeriodStartAndBillingPeriodEnd(UUID id,LocalDate start,LocalDate end);List<Invoice> findByCustomerIdOrderByCreatedAtDescIdDesc(UUID id);} @Repository public interface PaymentRepository extends JpaRepository<Payment,UUID>{} @Repository public interface IdempotencyRecordRepository extends JpaRepository<IdempotencyRecord,UUID>{Optional<IdempotencyRecord> findByKey(String key);} @Repository public interface UsageRecordRepository extends JpaRepository<UsageRecord,UUID>{Optional<UsageRecord> findByIdempotencyKey(String key);List<UsageRecord> findBySubscriptionIdAndTimestampGreaterThanEqualAndTimestampLessThanOrderByTimestampAscIdAsc(UUID id,OffsetDateTime start,OffsetDateTime end);} }
